/**
 * Problem: 2573. Find the String with LCP
 * Difficulty: Hard
 * Language: Java
 * 
 * Approach:
 * We are given an n x n LCP matrix and need to reconstruct the lexicographically
 * smallest string of length n that produces this exact matrix, or return "" if invalid.
 * 
 * 1. Greedy Reconstruction:
 *    - An entry lcp[i][j] > 0 implies word[i] == word[j].
 *    - To achieve the lexicographically smallest string, we greedily assign characters
 *      starting from 'a', 'b', ..., 'z' from index 0 to n - 1.
 *    - When we encounter an unassigned index i, we assign the next available character
 *      to i and all j >= i where lcp[i][j] > 0.
 *    - If we need more than 26 distinct characters, return "" immediately.
 * 
 * 2. Verification via Dynamic Programming:
 *    - The reconstructed word might not actually satisfy the given lcp matrix (due to
 *      transitivity violations, out-of-bound lengths, or invalid symmetries).
 *    - We compute the actual LCP matrix of word using the recurrence:
 *      expected = (word[i] == word[j]) ? (1 + (i + 1 < n && j + 1 < n ? lcp[i + 1][j + 1] : 0)) : 0
 *    - If at any cell lcp[i][j] != expected, the input matrix is invalid, return "".
 * 
 * Time Complexity: O(n^2)
 * Space Complexity: O(n) auxiliary space (excluding returned string)
 */

class Solution {
    public String findTheString(int[][] lcp) {
        int n = lcp.length;
        char[] word = new char[n];
        char curChar = 'a';

        for (int i = 0; i < n; i++) {
            if (word[i] == 0) {
                if (curChar > 'z') {
                    return "";
                }
                char ch = curChar++;
                for (int j = i; j < n; j++) {
                    if (lcp[i][j] > 0) {
                        word[j] = ch;
                    }
                }
            }
        }

        // Validate that word produces the exact LCP matrix
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                int expected = (word[i] == word[j])
                    ? (1 + (i + 1 < n && j + 1 < n ? lcp[i + 1][j + 1] : 0))
                    : 0;
                if (lcp[i][j] != expected) {
                    return "";
                }
            }
        }

        return new String(word);
    }
}

codes.Python:
"""
Problem: 2573. Find the String with LCP
Difficulty: Hard
Language: Python 3

Approach:
Greedily assign the earliest available lowercase letter to each unassigned position i
and every j >= i where lcp[i][j] > 0.
Then, verify that the constructed string generates the exact given lcp matrix
using bottom-up dynamic programming:
expected = (word[i] == word[j]) * (1 + (lcp[i + 1][j + 1] if i + 1 < n and j + 1 < n else 0))

Time Complexity: O(n^2)
Space Complexity: O(n) auxiliary space
"""

class Solution:
    def findTheString(self, lcp: list[list[int]]) -> str:
        n = len(lcp)
        word = [None] * n
        cur_char_code = ord('a')

        for i in range(n):
            if word[i] is None:
                if cur_char_code > ord('z'):
                    return ""
                ch = chr(cur_char_code)
                cur_char_code += 1
                for j in range(i, n):
                    if lcp[i][j] > 0:
                        word[j] = ch

        # Verify the constructed string produces the exact LCP matrix
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if word[i] == word[j]:
                    expected = 1 + (lcp[i + 1][j + 1] if i + 1 < n and j + 1 < n else 0)
                else:
                    expected = 0
                if lcp[i][j] != expected:
                    return ""

        return "".join(word)

codes.C++:
/**
 * Problem: 2573. Find the String with LCP
 * Difficulty: Hard
 * Language: C++
 * 
 * Approach:
 * 1. Greedily build the lexicographically smallest candidate string by scanning
 *    from 0 to n - 1 and assigning available letters ('a' through 'z') to positions
 *    where lcp[i][j] > 0.
 * 2. Check DP recurrence in reverse order to ensure the candidate string actually
 *    produces the given LCP matrix.
 * 
 * Time Complexity: O(n^2)
 * Space Complexity: O(n) auxiliary space (excluding returned string)
 */

#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    string findTheString(vector<vector<int>>& lcp) {
        int n = lcp.size();
        string word(n, '\0');
        char curChar = 'a';

        for (int i = 0; i < n; ++i) {
            if (word[i] == '\0') {
                if (curChar > 'z') {
                    return "";
                }
                char ch = curChar++;
                for (int j = i; j < n; ++j) {
                    if (lcp[i][j] > 0) {
                        word[j] = ch;
                    }
                }
            }
        }

        // Validate via bottom-up LCP recurrence
        for (int i = n - 1; i >= 0; --i) {
            for (int j = n - 1; j >= 0; --j) {
                int expected = (word[i] == word[j])
                    ? (1 + (i + 1 < n && j + 1 < n ? lcp[i + 1][j + 1] : 0))
                    : 0;
                if (lcp[i][j] != expected) {
                    return "";
                }
            }
        }

        return word;
    }
};

codes.JavaScript:
/**
 * Problem: 2573. Find the String with LCP
 * Difficulty: Hard
 * Language: JavaScript (ES6+)
 * 
 * Approach:
 * Greedily assign letters 'a' to 'z' to unassigned positions based on lcp[i][j] > 0.
 * Verify using DP recurrence lcp[i][j] === (word[i] === word[j] ? 1 + lcp[i+1][j+1] : 0).
 * 
 * Time Complexity: O(n^2)
 * Space Complexity: O(n) auxiliary space
 * 
 * @param {number[][]} lcp
 * @return {string}
 */
var findTheString = function(lcp) {
    const n = lcp.length;
    const word = new Array(n).fill(null);
    let curCode = 97; // 'a'

    for (let i = 0; i < n; i++) {
        if (word[i] === null) {
            if (curCode > 122) { // 'z'
                return "";
            }
            const ch = String.fromCharCode(curCode++);
            for (let j = i; j < n; j++) {
                if (lcp[i][j] > 0) {
                    word[j] = ch;
                }
            }
        }
    }

    // Validation via DP in reverse
    for (let i = n - 1; i >= 0; i--) {
        for (let j = n - 1; j >= 0; j--) {
            const expected = (word[i] === word[j])
                ? (1 + (i + 1 < n && j + 1 < n ? lcp[i + 1][j + 1] : 0))
                : 0;
            if (lcp[i][j] !== expected) {
                return "";
            }
        }
    }

    return word.join("");
};
